#requires -version 5.1
<#
OfficeLiteOptimizer.ps1
Stable entry point. Current embedded core: v3.0.0

Recommended launcher for old Windows 10/PowerShell 5.1:
[Net.ServicePointManager]::SecurityProtocol = 3072; iex ((New-Object Net.WebClient).DownloadString('https://raw.githubusercontent.com/Abestreid/pc/main/OfficeLiteOptimizer.ps1'))
#>

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = 3072

$payload = ''
$bytes = [Convert]::FromBase64String($payload)
$ms = New-Object IO.MemoryStream(,$bytes)
$gz = New-Object IO.Compression.GzipStream($ms,[IO.Compression.CompressionMode]::Decompress)
$sr = New-Object IO.StreamReader($gz,[Text.Encoding]::UTF8)
$core = $sr.ReadToEnd()
$sr.Dispose(); $gz.Dispose(); $ms.Dispose()

& ([ScriptBlock]::Create($core))
